{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "This bill would require every local education agency (LEA) and public charter school to designate one instructional day each school year to observe the Fourth of July. Students in grades K-12 would receive age- and grade-appropriate instruction on the founding of the United States, the Declaration of Independence, the U.S. Constitution, and American civic principles.",
      "rationale": "Conveys the annual observance and K–12 instruction requirement, but omits the colonies' separation from Great Britain and does not specifically convey instruction on citizens' fundamental rights and freedoms. The directors' responsibility is identified later in the summary."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "The bill sets specific learning objectives based on grade level.",
      "rationale": "Conveys prescribed grade-specific objectives, but omits the LEAs' and charter schools' responsibility to determine instructional programs and methods."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Students in grades K-5 would be introduced to basic concepts of independence and national symbols.",
      "rationale": "Conveys the introductory focus and national symbols, but omits the specific outcomes concerning the Fourth of July's meaning, the United States as an independent nation, freedom and individual rights, and symbols' connection to freedom and independence."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "Students in grades 6-8 would focus on the historical context of independence and civic principles, potentially through the social studies curriculum.",
      "rationale": "Conveys the grade band, general focus, and optional curricular placement, but omits the required outcomes concerning events leading to independence, reasons for colonial self-governance, the two founding documents' purpose and significance, and the specified civic principles."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "Students in grades 9-12 would analyze foundational texts and civic themes, potentially through the English language arts curriculum.",
      "rationale": "Conveys the grade band, analytical focus, and optional curricular placement, but omits the specific outcomes concerning the two founding texts, Revolution themes, independence's historical and philosophical significance, and connections to modern civic responsibilities and citizenship."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "Directors of schools for LEAs and public charter schools would be responsible for designating the day, ensuring consistent implementation across their schools, and verifying that the instruction aligns with state academic standards.",
      "rationale": "Conveys directors' duty to ensure consistent implementation, but omits their duty to provide implementation guidance as needed."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "Directors of schools for LEAs and public charter schools would be responsible for designating the day, ensuring consistent implementation across their schools, and verifying that the instruction aligns with state academic standards.",
      "rationale": "Conveys directors' standards-verification role, but omits verification of compliance with the section's requirements and the condition limiting standards alignment to instruction provided in social studies or English language arts classes."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "The bill requires that the instruction be nonpartisan, educational, and focused on historical facts and founding documents.",
      "rationale": "Conveys nonpartisanship and the historical and documentary focus, but omits the required focus on civic principles underlying the creation of the documents and the United States and does not convey that instruction must be solely educational."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "LEAs and charter schools must also periodically review and update their instructional materials.",
      "rationale": "Conveys periodic review and updating of materials, but omits content and methods, local discretion over appropriate updates, and the purposes of implementing civic-education best practices and ensuring conditional standards alignment."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law and apply starting with the 2026-2027 school year.",
      "rationale": "Conveys immediate effectiveness upon becoming law and ongoing application beginning in the specified school year."
    }
  ]
}
